// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ImageBake) predicate.ImageBake {
	return predicate.ImageBake(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ImageBake) predicate.ImageBake {
	return predicate.ImageBake(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ImageBake) predicate.ImageBake {
	return predicate.ImageBake(sql.NotPredicates(p))
}
